head.b:skin:
/* 정보마스터 theme (2026-10-22): 첫 화면·썸네일은 에디토리얼(B), 본문은 차분한 흰 바탕(A) */
:root{--ink:#161616;--paper:#f3eee3;--card:#ffffff;--muted:#4b4b4b;--line:#e4e1d8;--lemon:#f4d23c;--cobalt:#2b5fd9;--clay:#e2622e;--green:#23743f;--link:#1f5fd1}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font-family:'Pretendard Variable',Pretendard,-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo','Noto Sans KR',sans-serif;font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased;word-break:keep-all;overflow-wrap:break-word}
a{color:var(--link)}
img{max-width:100%;height:auto}
.wrap{max-width:1160px;margin:0 auto;padding:0 16px}
.serif{font-family:'Noto Serif KR',serif;font-weight:900;letter-spacing:-.02em}
.num{font-variant-numeric:tabular-nums}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.skip{position:absolute;left:-999px;top:8px;background:var(--ink);color:#fff;padding:8px 12px;z-index:9}
.skip:focus{left:8px}
/* header */
.site-head{background:var(--paper);border-bottom:2px solid var(--ink);position:relative;z-index:5}
.head-row{display:flex;align-items:center;gap:12px 28px;min-height:66px;flex-wrap:wrap}
.logo{display:flex;align-items:center;gap:10px;color:var(--ink);text-decoration:none;margin:0;font-size:22px}
.logo svg{flex:0 0 auto}
.nav{display:flex;align-items:center;gap:2px 22px;flex:1 1 auto;font-size:15px;font-weight:700}
.nav>a,.nav summary{color:var(--ink);text-decoration:none;padding:10px 0;cursor:pointer;list-style:none;display:block}
.nav summary::-webkit-details-marker{display:none}
.nav summary:after{content:"";display:inline-block;width:6px;height:6px;border-right:2px solid var(--ink);border-bottom:2px solid var(--ink);transform:rotate(45deg);margin:0 0 3px 7px}
.nav details{position:relative}
.nav details ul{position:absolute;left:-12px;top:100%;margin:0;padding:8px 0;list-style:none;background:#fff;border:2px solid var(--ink);box-shadow:4px 4px 0 var(--ink);min-width:220px}
.nav details li a{display:block;padding:9px 16px;color:var(--ink);text-decoration:none;font-weight:600}
.nav details li a:hover{background:#fbf3c9}
.nav>a:hover,.nav summary:hover{text-decoration:underline;text-underline-offset:6px;text-decoration-thickness:2px}
.search-box{position:relative}
.search-box summary{list-style:none;width:44px;height:44px;border:2px solid var(--ink);background:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer}
.search-box summary::-webkit-details-marker{display:none}
.search-box form{position:absolute;right:0;top:52px;display:flex;gap:6px;background:#fff;border:2px solid var(--ink);box-shadow:4px 4px 0 var(--ink);padding:10px;width:min(360px,calc(100vw - 32px))}
.search-box input{flex:1;min-width:0;height:44px;border:2px solid var(--ink);padding:0 12px;font:inherit}
.search-box button,.btn-ink{height:44px;border:2px solid var(--ink);background:var(--ink);color:var(--paper);font:inherit;font-weight:800;padding:0 16px;cursor:pointer}
/* home hero */
.hero{display:flex;flex-wrap:wrap;gap:28px 44px;align-items:center;padding:44px 0 36px}
.hero-text{flex:1 1 420px;min-width:0}
.kicker{display:inline-block;font-size:13px;font-weight:800;letter-spacing:.06em;border:2px solid var(--ink);background:#fff;padding:3px 10px}
.hero h1{font-size:44px;line-height:1.28;margin:16px 0 14px}
.hero p{font-size:17px;line-height:1.7;color:#333;margin:0 0 20px}
.hero form{display:flex;gap:8px;flex-wrap:wrap}
.hero input{flex:1 1 240px;min-width:0;height:54px;border:2px solid var(--ink);background:#fff;padding:0 16px;font:inherit;font-size:16px}
.hero .btn-ink{height:54px;padding:0 24px}
.hero-list{flex:1 1 420px;min-width:0;border:2px solid var(--ink);background:#fff;box-shadow:6px 6px 0 var(--ink)}
.hero-list h2{margin:0;font-size:15px;font-weight:800;padding:12px 18px;background:var(--lemon);border-bottom:2px solid var(--ink)}
.hero-list a{display:flex;gap:6px 16px;align-items:baseline;flex-wrap:wrap;padding:16px 18px;border-bottom:1px solid var(--ink);color:var(--ink);text-decoration:none}
.hero-list a:last-child{border-bottom:0}
.hero-list a:hover{background:#fbf6e6}
.hero-list b{font-size:26px;font-weight:800;letter-spacing:-.02em;flex:0 0 auto}
.hero-list span{font-size:15px;color:#333}
/* calculator tiles */
.tiles{border-top:2px solid var(--ink);border-bottom:2px solid var(--ink);background:#fff}
.tiles .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));padding:0}
.tile{display:flex;flex-direction:column;gap:8px;padding:24px 22px;text-decoration:none;border-right:2px solid var(--ink);min-height:148px}
.tile:last-child{border-right:0}
.tile small{font-size:12px;font-weight:800;letter-spacing:.08em}
.tile strong{font-family:'Noto Serif KR',serif;font-weight:900;font-size:24px;letter-spacing:-.02em}
.tile span{font-size:14px;line-height:1.55;font-weight:500}
.tile:hover strong{text-decoration:underline;text-underline-offset:5px}
.t-cobalt{background:var(--cobalt);color:#fff}.t-lemon{background:var(--lemon);color:var(--ink)}.t-clay{background:var(--clay);color:var(--ink)}.t-green{background:var(--green);color:#fff}
/* lists */
.sec-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px;flex-wrap:wrap;border-bottom:2px solid var(--ink);padding-bottom:10px;margin:40px 0 22px}
.sec-head h2,.sec-head h1{margin:0;font-size:26px}
.sec-head a{font-size:14px;font-weight:800;color:var(--ink)}
.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:26px}
.card{display:flex;flex-direction:column;background:#fff;border:2px solid var(--ink);color:var(--ink);text-decoration:none;transition:transform .12s,box-shadow .12s}
.card:hover{transform:translate(-2px,-2px);box-shadow:5px 5px 0 var(--ink)}
.card-img{aspect-ratio:3/2;background:var(--cobalt);border-bottom:2px solid var(--ink);overflow:hidden}
.card-img img{width:100%;height:100%;object-fit:cover;display:block}
.card-body{padding:16px 18px 20px;display:flex;flex-direction:column;gap:8px}
.card-meta{font-size:13px;font-weight:700;color:#444}
.card h3{margin:0;font-family:'Noto Serif KR',serif;font-weight:900;font-size:20px;line-height:1.45;letter-spacing:-.01em}
.ad-feed{grid-column:1/-1;min-height:120px}
.pager{display:flex;justify-content:center;margin:34px 0 10px}
.pager a{display:inline-block;border:2px solid var(--ink);background:#fff;color:var(--ink);font-weight:800;text-decoration:none;padding:12px 26px;box-shadow:4px 4px 0 var(--ink)}
/* post (A: calm white reading) */
.post-wrap{display:flex;flex-wrap:wrap;gap:28px;align-items:flex-start;padding:28px 0 56px}
.post-main{flex:999 1 600px;min-width:0;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:32px 36px 40px}
.rail{flex:1 1 280px;min-width:0;display:flex;flex-direction:column;gap:20px}
.crumb{display:flex;gap:6px;flex-wrap:wrap;font-size:14px;color:#555;margin:0 0 12px}
.crumb a{color:#555;text-decoration:none}
.crumb a:hover{text-decoration:underline}
.post-title{font-size:32px;line-height:1.38;font-weight:800;letter-spacing:-.03em;margin:0 0 14px}
.post-meta{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:0 0 26px;padding-bottom:20px;border-bottom:1px solid var(--line)}
.badge{font-size:13px;font-weight:700;padding:5px 12px;border-radius:999px;background:#eef3fd;color:#1a4fb8;text-decoration:none}
.badge-date{background:#fff6d6;color:#5a4500}
.badge-author{background:var(--ink);color:#fff}
.post-body{font-size:17px;line-height:1.85;color:#222}
.post-body p{margin:0 0 1.1em}
.post-body h2{font-size:24px;line-height:1.4;letter-spacing:-.02em;margin:1.9em 0 .7em;padding-top:.2em}
.post-body h3{font-size:19px;line-height:1.45;margin:1.5em 0 .6em}
.post-body ul,.post-body ol{padding-left:1.3em;margin:0 0 1.2em}
.post-body li{margin:.3em 0}
.post-body img{border-radius:10px}
.post-body table{border-collapse:collapse;width:100%;margin:1.2em 0;font-size:15.5px;display:block;overflow-x:auto;font-variant-numeric:tabular-nums}
.post-body th,.post-body td{border:1px solid #e1e4ea;padding:10px 12px;text-align:left;vertical-align:top}
.post-body th{background:#f5f7fa;font-weight:700}
.post-body blockquote{margin:1.2em 0;padding:12px 18px;background:#f6f7f9;border-radius:10px}
.post-body pre{overflow-x:auto}
.post-body a{word-break:break-all}
.post-note{margin:34px 0 0;padding:18px 20px;background:#f6f7f9;border-radius:12px;font-size:14px;line-height:1.7;color:#444}
.post-note b{color:var(--ink)}
.ad-mid{margin:26px 0;min-height:100px}
.rail-box{background:#fff;border:1px solid var(--line);border-radius:16px;padding:20px}
.rail-box h2{margin:0 0 10px;font-size:16px;font-weight:800}
.rail-calc{background:var(--cobalt);color:#fff;border:2px solid var(--ink);border-radius:0;box-shadow:6px 6px 0 var(--ink)}
.rail-calc h2{font-family:'Noto Serif KR',serif;font-weight:900;font-size:21px}
.rail-calc a{display:block;color:#fff;text-decoration:none;padding:9px 0;border-top:1px solid rgba(255,255,255,.35);font-weight:600}
.rail-calc a:hover{text-decoration:underline}
.rail-calc .all{margin-top:8px;text-align:center;background:var(--lemon);color:var(--ink);border:2px solid var(--ink);font-weight:800}
.empty{padding:40px 0;text-align:center}
/* post body blocks from templates/post.html.j2 (im-*) */
.im-hero{margin:0 0 24px}.im-hero img{width:100%;display:block;border-radius:12px}
.im-figure{margin:22px 0;text-align:center}.im-figure img{border-radius:12px}
.post-body .im-lead{font-size:1.12em;line-height:1.8;font-weight:500;color:#161616}
.im-calc{margin:20px 0;padding:18px 20px;background:#f2f6fd;border:1px solid #dbe5f6;border-radius:14px}
.im-calc p{margin:0 0 12px!important}
.im-btn{display:block;text-align:center;padding:14px 18px;background:var(--ink);color:#fff!important;border-radius:12px;text-decoration:none!important;font-weight:800;font-size:1.02em;word-break:keep-all!important}
.im-btn:hover{background:#000}
.im-calc-end{background:#fbf6e6;border-color:#efe3bd}
.post-body .im-tip{padding:14px 16px;background:#fbf6e6;border-radius:10px;font-size:.97em}
.post-body .im-related{padding:12px 16px;background:#f6f7f9;border-radius:10px;font-size:.97em}
.post-body .im-asof,.post-body .im-muted{font-size:.9em;color:#555}
.im-box{margin:20px 0;padding:18px 20px;background:#f6f7f9;border-radius:14px}
.im-box-title{font-weight:800;margin:0 0 8px!important}
.im-code{margin:0;padding:10px 12px;background:#1e1e1e;color:#f5f5f5;border-radius:8px;overflow-x:auto;white-space:pre}
.im-points li::marker{color:var(--cobalt)}
.im-sources{font-size:.92em;color:#444}
.im-footer{text-align:center}
.post-body strong{font-weight:800;color:#161616}
/* footer */
.site-foot{background:var(--ink);color:#e9e4d8;margin-top:40px}
.site-foot .wrap{padding-top:34px;padding-bottom:40px;display:flex;flex-direction:column;gap:12px}
.site-foot p{margin:0;font-size:14px;line-height:1.7;color:#d6d0c2}
.site-foot nav{display:flex;flex-wrap:wrap;gap:6px 20px;font-size:14px;font-weight:700}
.site-foot a{color:#f3eee3}
.site-foot a.hl{color:var(--lemon)}
@media (max-width:900px){.tiles .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}.tile:nth-child(2){border-right:0}.tile:nth-child(-n+2){border-bottom:2px solid var(--ink)}}
@media (max-width:720px){
.head-row{min-height:58px;gap:6px 16px}
.nav{order:3;flex:1 1 100%;overflow-x:auto;gap:0 18px;padding-bottom:2px;white-space:nowrap}
.nav details ul{position:fixed;left:16px;right:16px;top:auto;min-width:0}
.search-box{margin-left:auto}
.hero{padding:28px 0 26px}.hero h1{font-size:32px}
.grid{grid-template-columns:1fr;gap:20px}
.post-main{padding:22px 18px 28px;border-radius:12px}
.post-title{font-size:26px}
.post-body{font-size:16.5px}
.post-body h2{font-size:21px}
.sec-head h2,.sec-head h1{font-size:22px}
}
@media (max-width:480px){.tiles .wrap{grid-template-columns:1fr}.tile{border-right:0;border-bottom:2px solid var(--ink);min-height:0}.tile:last-child{border-bottom:0}}

body.script:
//
(function(){
  var ad=document.getElementById('ad-mid');
  var body=document.querySelector('.post-body');
  if(ad&&body){
    var hs=body.querySelectorAll('h2');
    if(hs.length>=3){body.insertBefore(ad,hs[Math.floor(hs.length/2)]);}
  }
  document.querySelectorAll('.nav details').forEach(function(d){
    d.addEventListener('toggle',function(){if(d.open){document.querySelectorAll('.nav details').forEach(function(o){if(o!==d)o.open=false;});}});
  });
  document.addEventListener('click',function(e){
    document.querySelectorAll('.nav details[open],.search-box[open]').forEach(function(d){if(!d.contains(e.target))d.open=false;});
  });
})();
//
